import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { createRoot } from "react-dom/client";
import { invoke } from "@tauri-apps/api/core";
import "./style.css";
import "./forms.css";

type Gift = { id: string; name: string; imageUrl?: string; coinCost?: number; costVerified: boolean; active: boolean; requiredQuantity: number; effectIds: string[]; cooldownMs: number; priority: number };
type EventLine = { id: string; text: string; tone: string; createdAt: string; username?: string; giftName?: string; quantity?: number; effectId?: string; status?: string; latencyMs?: number; error?: string };
type Stats = { giftsReceived: number; effectsQueued: number; effectsSucceeded: number; effectsFailed: number; queueDepth?: number; activeEffects?: number; averageLatencyMs?: number };
type EffectConfig = { id: string; name: string; description: string; category: string; defaultDurationMs: number; intensity: number; probability: number; cooldownMs: number; priority?: number; parameters?: Record<string, unknown>; conditions?: Record<string, unknown>; compatibility: "legacy" | "enhanced" | "both"; updatedAt: string };
type LocalServicesStatus = { orchestrator: boolean; overlay: boolean; dashboard: boolean };
type LocalResourceStatus = { memoryMb: number; processCount: number };
type LocalGameStatus = { enhanced: boolean; legacy: boolean; path?: string };
type AnalyticsBreakdown = { gifts: Record<string, number>; effects: Record<string, number>; users: Record<string, number> };
type OverlayConfig = { gameplayShare: number; columns: 4 | 5 | 6; visibleCount: number; compact: boolean; fontScale: number; gap: number; backgroundOpacity: number; alertDurationMs: number; soundEnabled: boolean; iconScale: number; cardBackground: string; cardBorder: string };
type PerformanceConfig = { profile: "low" | "balanced" | "high"; queueLimit: number; maxActiveEffects: number };
type SessionSummary = { id: string; startedAt: string; endedAt?: string; giftsReceived: number; effectsQueued: number; effectsSucceeded: number; effectsFailed: number; updatedAt: string };
const nav = ["Command", "Gift manager", "Effects", "Live Monitor", "Overlay studio", "Analytics"] as const;
const effects = [{ id: "player.ragdoll", name: "Ragdoll", category: "PLAYER", state: "implemented" }, { id: "player.recover_health", name: "Recover health", category: "PLAYER", state: "implemented" }, { id: "player.invincibility", name: "Temporary invincibility", category: "PLAYER", state: "implemented" }, { id: "player.super_jump", name: "Super jump", category: "PLAYER", state: "implemented" }, { id: "player.speed_boost", name: "Speed boost", category: "PLAYER", state: "implemented" }, { id: "player.change_weapon", name: "Change weapon", category: "PLAYER", state: "implemented" }, { id: "player.wanted_level", name: "Wanted level", category: "PLAYER", state: "implemented" }, { id: "player.clear_wanted", name: "Clear wanted level", category: "PLAYER", state: "implemented" }, { id: "player.remove_weapons", name: "Remove weapons", category: "PLAYER", state: "implemented" }, { id: "world.weather", name: "Weather shift", category: "WORLD", state: "implemented" }, { id: "world.time", name: "Time shift", category: "WORLD", state: "implemented" }, { id: "vehicle.spin", name: "Vehicle spin", category: "VEHICLE", state: "implemented" }, { id: "vehicle.engine_off", name: "Engine off", category: "VEHICLE", state: "implemented" }];
function safeImageUrl(value?: string) { if (typeof value === "string" && value.length <= 700_000 && /^data:image\/(?:png|jpe?g|gif|webp);base64,[A-Za-z0-9+/=\s]+$/i.test(value)) return value; try { const url = new URL(String(value)); return url.protocol === "https:" || url.protocol === "http:" ? url.toString() : undefined; } catch { return undefined; } }
function effectLabel(effectId: string) { return effects.find((effect) => effect.id === effectId)?.name || effectId; }
function formatEventTime(value: string) { const parsed = new Date(value); return Number.isNaN(parsed.getTime()) ? "--:--:--" : parsed.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }); }

function App() {
  const [view, setView] = useState<(typeof nav)[number]>("Command");
  const [socket, setSocket] = useState<WebSocket | null>(null);
  const [events, setEvents] = useState<EventLine[]>([]);
  const [catalog, setCatalog] = useState<Gift[]>([]);
  const [effectConfigs, setEffectConfigs] = useState<EffectConfig[]>([]);
  const [connected, setConnected] = useState(false);
  const [tiktokState, setTiktokState] = useState("disconnected");
  const [gtaState, setGtaState] = useState("disconnected");
  const [chaos, setChaos] = useState({ points: 0, level: 0 });
  const [stats, setStats] = useState<Stats>({ giftsReceived: 0, effectsQueued: 0, effectsSucceeded: 0, effectsFailed: 0 });
  const [performance, setPerformance] = useState<PerformanceConfig>({ profile: "balanced", queueLimit: 100, maxActiveEffects: 24 });
  const [sessions, setSessions] = useState<SessionSummary[]>([]);
  const [localServices, setLocalServices] = useState<LocalServicesStatus>({ orchestrator: false, overlay: false, dashboard: false });
  const [resources, setResources] = useState<LocalResourceStatus>({ memoryMb: 0, processCount: 0 });
  const [gameStatus, setGameStatus] = useState<LocalGameStatus>({ enhanced: false, legacy: false });
  const [breakdown, setBreakdown] = useState<AnalyticsBreakdown>({ gifts: {}, effects: {}, users: {} });
  const [tiktokUsername, setTiktokUsername] = useState("");
  const [runtimeNotice, setRuntimeNotice] = useState("");
  const [diagnostic, setDiagnostic] = useState("");
  const [gtaPath, setGtaPath] = useState("");
  const [installConsent, setInstallConsent] = useState("");
  const [allowOverwrite, setAllowOverwrite] = useState(false);
  const [chaosToken, setChaosToken] = useState(() => localStorage.getItem("gcl.chaosToken") || "");
  const [authTokenLoaded, setAuthTokenLoaded] = useState(false);
  const pendingMessages = useRef<string[]>([]);

  useEffect(() => { invoke<string>("local_auth_token").then((token) => { if (token) { setChaosToken(token); localStorage.setItem("gcl.chaosToken", token); } }).catch(() => undefined).finally(() => setAuthTokenLoaded(true)); }, []);

  useEffect(() => {
    let disposed = false;
    let retryMs = 500;
    let retryTimer: number | undefined;
    let current: WebSocket | undefined;
    if (!authTokenLoaded) return () => undefined;
    const connect = () => {
      if (disposed) return;
      const ws = new WebSocket("ws://127.0.0.1:39177");
      current = ws;
      ws.onopen = () => {
        retryMs = 500;
        ws.send(JSON.stringify({ protocolVersion: 1, type: "auth.hello", payload: { token: chaosToken, client: "dashboard" } }));
        for (const pending of pendingMessages.current.splice(0)) ws.send(pending);
        setConnected(true);
        setSocket(ws);
      };
      ws.onclose = () => { if (current === ws) { setConnected(false); setSocket(null); } if (!disposed) { retryTimer = window.setTimeout(connect, retryMs); retryMs = Math.min(10_000, retryMs * 2); } };
      ws.onmessage = (message) => {
        try {
          const envelope = JSON.parse(message.data);
          if (envelope.type === "catalog.snapshot") setCatalog(envelope.payload);
          if (envelope.type === "chaos.snapshot") setChaos(envelope.payload);
          if (envelope.type === "stats.snapshot") setStats(envelope.payload);
          if (envelope.type === "effects.snapshot") setEffectConfigs(envelope.payload);
          if (envelope.type === "performance.config") setPerformance(envelope.payload);
          if (envelope.type === "sessions.snapshot") setSessions(envelope.payload);
          if (envelope.type === "analytics.snapshot") { setBreakdown(envelope.payload); setStats((current) => ({ ...current, averageLatencyMs: envelope.payload.averageLatencyMs })); }
          if (envelope.type === "service.status") { setGtaState(envelope.payload.gta); setTiktokState(envelope.payload.tiktok); }
          if (envelope.type === "live.status") { setTiktokState(envelope.payload.state); addEvent(`live-${Date.now()}`, `TikTok LIVE · ${envelope.payload.state}`, "normal", envelope.payload.updatedAt, { status: envelope.payload.state }); }
          if (envelope.type === "result") { const result = envelope.payload; const subject = result.username ? `${result.username} · ${result.giftName || "gift"} × ${result.quantity || 1}` : "system"; const effect = result.effectId ? ` · ${result.effectId}` : ""; const latency = typeof result.latencyMs === "number" ? ` · ${result.latencyMs}ms` : ""; if (result.status === "accepted" && result.giftName) setBreakdown((current) => ({ ...current, gifts: { ...current.gifts, [result.giftName]: (current.gifts[result.giftName] || 0) + 1 }, users: result.username ? { ...current.users, [result.username]: (current.users[result.username] || 0) + 1 } : current.users })); if (result.status === "succeeded" && result.effectId) setBreakdown((current) => ({ ...current, effects: { ...current.effects, [result.effectId]: (current.effects[result.effectId] || 0) + 1 } })); addEvent(result.id, `${subject}${effect} · ${result.status}${result.error ? ` · ${result.error}` : ""}${latency}`, result.status === "succeeded" ? "good" : "normal", result.createdAt, { username: result.username, giftName: result.giftName, quantity: result.quantity, effectId: result.effectId, status: result.status, latencyMs: result.latencyMs, error: result.error }); }
        } catch { /* ignore malformed local frames */ }
      };
    };
    connect();
    return () => { disposed = true; if (retryTimer) window.clearTimeout(retryTimer); current?.close(); };
  }, [chaosToken, authTokenLoaded]);

  useEffect(() => {
    const refresh = () => invoke<LocalServicesStatus>("local_services_status").then(setLocalServices).catch(() => undefined);
    refresh();
    const timer = window.setInterval(refresh, 3000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    const refresh = () => invoke<LocalGameStatus>("local_game_status").then(setGameStatus).catch(() => undefined);
    refresh();
    const timer = window.setInterval(refresh, 3000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    const refresh = () => invoke<LocalResourceStatus>("local_resource_status").then(setResources).catch(() => undefined);
    refresh();
    const timer = window.setInterval(refresh, 5000);
    return () => window.clearInterval(timer);
  }, []);

  function addEvent(id: string, text: string, tone = "normal", createdAt = new Date().toISOString(), details: Partial<EventLine> = {}) { const timestamp = formatEventTime(createdAt); setEvents((items) => [{ id: `${id}-${Date.now()}`, text: `${timestamp} · ${text}`, tone, createdAt, ...details }, ...items].slice(0, 10)); }
  function send(type: string, payload: unknown) {
    const serialized = JSON.stringify({ protocolVersion: 1, type, payload });
    if (socket?.readyState === WebSocket.OPEN) socket.send(serialized);
    else {
      pendingMessages.current.push(serialized);
      if (pendingMessages.current.length > 50) pendingMessages.current.splice(0, pendingMessages.current.length - 50);
    }
  }
  function sendTestGift() {
    const now = new Date().toISOString();
    send("catalog.upsert", { id: "test-gift", name: "Test gift", costVerified: false, active: true, requiredQuantity: 1, effectIds: ["player.ragdoll"], cooldownMs: 1000, priority: 1 });
    send("gift.event", { id: crypto.randomUUID(), username: "dashboard_tester", giftId: "test-gift", giftName: "Test gift", quantity: 1, createdAt: now, source: "simulator" });
  }
  function showRuntimeError(error: unknown) { setRuntimeNotice(typeof error === "string" ? error : `Runtime command failed: ${String(error)}`); }
  function startLocalServices() { setRuntimeNotice("Starting local services…"); invoke<string>("start_local_services").then((message) => setRuntimeNotice(message || "Local services started.")).catch(showRuntimeError); }
  function stopLocalServices() { setRuntimeNotice("Stopping local services…"); invoke<string>("stop_local_services").then((message) => setRuntimeNotice(message || "Local services stopped.")).catch(showRuntimeError); }
  function startTikTokConnector() { if (!tiktokUsername.trim()) { setRuntimeNotice("Enter a TikTok username first."); return; } setRuntimeNotice("Starting TikTok connector…"); invoke<string>("start_tiktok_connector", { username: tiktokUsername.trim() }).then((message) => setRuntimeNotice(message || "TikTok connector started.")).catch(showRuntimeError); }
  function stopTikTokConnector() { setRuntimeNotice("Stopping TikTok connector…"); invoke<string>("stop_tiktok_connector").then((message) => setRuntimeNotice(message || "TikTok connector stopped.")).catch(showRuntimeError); }
  function runDiagnostic() { setRuntimeNotice("Running read-only GTA diagnostic…"); invoke<string>("run_diagnostic").then((report) => { setDiagnostic(report); setRuntimeNotice("Diagnostic completed without changing the game installation."); }).catch(showRuntimeError); }
  function installMod() { if (!gtaPath.trim()) { setRuntimeNotice("Enter the GTA V Enhanced installation path first."); return; } setRuntimeNotice("Installing the Story Mode mod…"); invoke<string>("install_mod", { gtaPath: gtaPath.trim(), consent: installConsent, allowOverwrite }).then((message) => setRuntimeNotice(message || "Mod installed. Start Story Mode to test it.")).catch(showRuntimeError); }
  function uninstallMod() { if (!gtaPath.trim()) { setRuntimeNotice("Enter the GTA V Enhanced installation path first."); return; } if (!window.confirm("Remove GtaChaosLive.dll from this GTA installation? A recoverable backup will be kept.")) return; setRuntimeNotice("Removing the Story Mode mod…"); invoke<string>("uninstall_mod", { gtaPath: gtaPath.trim(), consent: installConsent }).then((message) => setRuntimeNotice(message || "Mod removed; backup kept.")).catch(showRuntimeError); }
  function profileOperation(operation: "export" | "import" | "backup") { const labels = { export: "Export profile JSON to", import: "Import profile JSON from", backup: "Create SQLite backup at" }; const file = window.prompt(labels[operation], operation === "export" ? "gta-chaos-profile.json" : operation === "backup" ? "chaos-live-backup.db" : "gta-chaos-profile.json"); if (!file?.trim()) return; setRuntimeNotice(`${operation} profile…`); invoke<string>("profile_operation", { operation, file: file.trim() }).then((message) => setRuntimeNotice(message || "Profile operation completed.")).catch(showRuntimeError); }
  const streamState = useMemo(() => connected ? "ready" : "offline", [connected]);
  const activeGiftCount = catalog.filter((gift) => gift.active).length;

  return <main>
    <aside><div className="brand"><span>GCL</span><strong>GTA<br />CHAOS<br />LIVE</strong></div><nav>{nav.map((item) => <button key={item} className={view === item ? "active" : ""} onClick={() => setView(item)}>{item}</button>)}</nav><div className="version">BUILD 0.1.0 · STORY MODE ONLY</div></aside>
    <section className="content"><header><div><p className="eyebrow">LOCAL CONTROL ROOM / {String(nav.indexOf(view) + 1).padStart(2, "0")}</p><h1>{view === "Command" ? <>Make the city <em>unpredictable.</em></> : view}</h1><p className="muted">One controlled bridge between live gifts, GTA V Enhanced and your OBS scene.</p>{runtimeNotice && <p className="runtime-notice">{runtimeNotice}</p>}</div><div className="header-actions"><button className="resume" onClick={() => setView("Overlay studio")}>▣ Open Overlay Studio</button><button className="resume" onClick={startLocalServices}>▶ Start system</button><button className="resume" onClick={stopLocalServices}>■ Stop services</button><button className="resume" onClick={() => send("system.pause", { reason: "dashboard_manual_pause" })}>Ⅱ Pause effects</button><button className="resume" onClick={() => send("system.resume", { reason: "dashboard_manual_resume" })}>↻ Resume effects</button><button className="stop" onClick={() => send("system.stop", { reason: "dashboard_emergency_stop" })}>■ Emergency stop</button></div></header>
      {view === "Command" && <CommandView connected={connected} gtaState={gtaState} gameStatus={gameStatus} tiktokState={tiktokState} localServices={localServices} resources={resources} diagnostic={diagnostic} runDiagnostic={runDiagnostic} gtaPath={gtaPath} setGtaPath={setGtaPath} installConsent={installConsent} setInstallConsent={setInstallConsent} allowOverwrite={allowOverwrite} setAllowOverwrite={setAllowOverwrite} installMod={installMod} uninstallMod={uninstallMod} streamState={streamState} stats={stats} chaos={chaos} events={events} performance={performance} onPerformanceChange={(profile) => send("performance.config", { profile, queueLimit: profile === "low" ? 25 : profile === "high" ? 120 : 100, maxActiveEffects: profile === "low" ? 8 : profile === "high" ? 48 : 24 })} sendTestGift={sendTestGift} tiktokUsername={tiktokUsername} setTiktokUsername={setTiktokUsername} startTikTokConnector={startTikTokConnector} stopTikTokConnector={stopTikTokConnector} onProfileOperation={profileOperation} />}
      {view === "Gift manager" && <><GiftManagerEditor catalog={catalog} activeGiftCount={activeGiftCount} onUpsert={(gift) => send("catalog.upsert", gift)} onRemove={(id) => send("catalog.remove", { id })} /><GiftEffectReference catalog={catalog} configs={effectConfigs} /></>}
      {view === "Effects" && <EffectsView configs={effectConfigs} onSave={(config) => send("effect.upsert", config)} onTest={(effectId, parameters) => send("effect.command", { id: crypto.randomUUID(), effectId, parameters, createdAt: new Date().toISOString(), expiresAt: new Date(Date.now() + 15000).toISOString() })} />}
      {view === "Live Monitor" && <LiveMonitorView events={events} stats={stats} streamState={streamState} />}
      {view === "Overlay studio" && <OverlayViewFunctional catalog={catalog} chaos={chaos} chaosToken={chaosToken} onConfigChange={(config) => send("overlay.config", config)} />}
      {view === "Analytics" && <AnalyticsView events={events} catalog={catalog} stats={stats} breakdown={breakdown} />}
      {view === "Analytics" && <SessionHistory sessions={sessions} />}
    </section>
  </main>;
}

function StatusCards({ connected, gtaState, gameStatus, tiktokState, localServices }: { connected: boolean; gtaState: string; gameStatus: LocalGameStatus; tiktokState: string; localServices: LocalServicesStatus }) { const overlayReady = localServices.overlay; const gtaReady = gtaState === "connected"; const gtaDetected = gameStatus.enhanced || gameStatus.legacy; const cards = [["01", "Orchestrator", connected && localServices.orchestrator ? "ready" : "offline", connected && localServices.orchestrator ? "WebSocket handshake complete" : "Start the local event spine"], ["02", "GTA V Enhanced", gtaReady ? "ready" : gtaDetected ? "detected" : "pending", gtaReady ? "Mod handshake detected" : gameStatus.enhanced ? "GTA5_Enhanced.exe detected; awaiting mod" : gameStatus.legacy ? "Legacy GTA detected; Enhanced required" : "GTA process not detected"], ["03", "TikTok LIVE", tiktokState === "connected" ? "ready" : tiktokState, tiktokState === "connected" ? "Connector connected" : "Use local events for testing"], ["04", "OBS Overlay", overlayReady ? "ready" : "offline", overlayReady ? "Preview at 1080 × 1920" : "Start the overlay server"]]; return <div className="status-grid">{cards.map(([n, name, status, hint]) => <article className="status-card" key={name}><span className="num">{n}</span><span className={`dot ${status}`}></span><h3>{name}</h3><p>{hint}</p><small>{status}</small></article>)}</div>; }
function EventRow({ event }: { event: EventLine }) { return <div className={`event-row ${event.tone}`}><time>{formatEventTime(event.createdAt)}</time><span>{event.username || "—"}</span><span>{event.giftName || "—"}{event.quantity ? ` ×${event.quantity}` : ""}</span><span>{event.effectId || "—"}</span><span>{event.status || "—"}</span><span>{typeof event.latencyMs === "number" ? `${event.latencyMs} ms` : "—"}</span><span className="event-error">{event.error || ""}</span></div>; }
function CommandView({ connected, gtaState, gameStatus, tiktokState, localServices, resources, diagnostic, runDiagnostic, gtaPath, setGtaPath, installConsent, setInstallConsent, allowOverwrite, setAllowOverwrite, installMod, uninstallMod, streamState, stats, chaos, events, performance, onPerformanceChange, sendTestGift, tiktokUsername, setTiktokUsername, startTikTokConnector, stopTikTokConnector, onProfileOperation }: { connected: boolean; gtaState: string; gameStatus: LocalGameStatus; tiktokState: string; localServices: LocalServicesStatus; resources: LocalResourceStatus; diagnostic: string; runDiagnostic: () => void; gtaPath: string; setGtaPath: (value: string) => void; installConsent: string; setInstallConsent: (value: string) => void; allowOverwrite: boolean; setAllowOverwrite: (value: boolean) => void; installMod: () => void; uninstallMod: () => void; streamState: string; stats: Stats; chaos: { points: number; level: number }; events: EventLine[]; performance: PerformanceConfig; onPerformanceChange: (profile: PerformanceConfig["profile"]) => void; sendTestGift: () => void; tiktokUsername: string; setTiktokUsername: (value: string) => void; startTikTokConnector: () => void; stopTikTokConnector: () => void; onProfileOperation: (operation: "export" | "import" | "backup") => void }) { return <><StatusCards connected={connected} gtaState={gtaState} gameStatus={gameStatus} tiktokState={tiktokState} localServices={localServices} /><HomeMetrics stats={stats} chaos={chaos} /><ResourceCard resources={resources} /><DiagnosticCard report={diagnostic} onRun={runDiagnostic} /><InstallModCard gtaPath={gtaPath} setGtaPath={setGtaPath} consent={installConsent} setConsent={setInstallConsent} allowOverwrite={allowOverwrite} setAllowOverwrite={setAllowOverwrite} onInstall={installMod} onUninstall={uninstallMod} /><PerformanceCard config={performance} onChange={onPerformanceChange} /><ProfileCard onOperation={onProfileOperation} /><TikTokControls username={tiktokUsername} setUsername={setTiktokUsername} onStart={startTikTokConnector} onStop={stopTikTokConnector} /><div className="lower"><article className="panel event-panel"><PanelTitle eyebrow="EVENT STREAM" title="Live monitor"><span className="pulse">● {streamState}</span></PanelTitle><div className="event-body">{events.length === 0 ? <><span className="cross">＋</span><strong>No live events yet</strong><p>Start the simulator or connect TikTok LIVE to see normalized events here.</p></> : <div className="events">{events.map((event) => <EventRow event={event} />)}</div>}<button onClick={sendTestGift}>Send test gift</button></div></article><ChaosPanel chaos={chaos} /></div></>; }
function HomeMetrics({ stats, chaos }: { stats: Stats; chaos: { points: number; level: number } }) { return <div className="analytics-grid home-metrics"><article className="metric"><small>GIFTS RECEIVED</small><strong>{stats.giftsReceived}</strong></article><article className="metric"><small>EFFECTS EXECUTED</small><strong>{stats.effectsSucceeded}</strong></article><article className="metric"><small>EFFECTS ACTIVE</small><strong>{stats.activeEffects ?? 0}</strong></article><article className="metric"><small>EVENT QUEUE</small><strong>{stats.queueDepth ?? 0}</strong></article><article className="metric"><small>CHAOS LEVEL</small><strong>{chaos.level}</strong></article></div>; }
function DiagnosticCard({ report, onRun }: { report: string; onRun: () => void }) { return <article className="panel"><PanelTitle eyebrow="INSTALLATION CHECK" title="GTA diagnostic"><button className="secondary" onClick={onRun}>Run read-only check</button></PanelTitle><p className="muted">Checks GTA Enhanced, Script Hook V, SHVDN Enhanced, WebView2, local runtimes and localhost communication. It never copies files.</p>{report ? <pre className="diagnostic-output">{report}</pre> : <p className="muted">No diagnostic has been run in this session.</p>}</article>; }
function InstallModCard({ gtaPath, setGtaPath, consent, setConsent, allowOverwrite, setAllowOverwrite, onInstall, onUninstall }: { gtaPath: string; setGtaPath: (value: string) => void; consent: string; setConsent: (value: string) => void; allowOverwrite: boolean; setAllowOverwrite: (value: boolean) => void; onInstall: () => void; onUninstall: () => void }) { return <article className="panel"><PanelTitle eyebrow="STORY MODE ONLY" title="Install GTA mod" /><p className="muted">Copies only GtaChaosLive.dll after checking GTA V Enhanced, Script Hook V and SHVDN Enhanced. Third-party components are never downloaded.</p><div className="connector-form"><input aria-label="GTA V Enhanced path" placeholder="GTA V Enhanced folder" value={gtaPath} onChange={(event) => setGtaPath(event.target.value)} /><input aria-label="Installation consent" placeholder="I UNDERSTAND STORY MODE ONLY" value={consent} onChange={(event) => setConsent(event.target.value)} /><label><input type="checkbox" checked={allowOverwrite} onChange={(event) => setAllowOverwrite(event.target.checked)} /> Allow backup + overwrite</label><button onClick={onInstall}>Install mod</button><button className="secondary" onClick={onUninstall}>Uninstall mod</button></div><p className="muted">Uninstall moves the DLL to a timestamped recoverable backup; it does not touch third-party files.</p></article>; }
function ResourceCard({ resources }: { resources: LocalResourceStatus }) { return <article className="panel resource-card"><PanelTitle eyebrow="LOCAL RUNTIME" title="Resource usage" /><div className="resource-values"><strong>{resources.memoryMb.toFixed(1)} MB</strong><span>{resources.processCount} Node/Python processes detected</span></div></article>; }
function PerformanceCard({ config, onChange }: { config: PerformanceConfig; onChange: (profile: PerformanceConfig["profile"]) => void }) { return <article className="panel performance-card"><PanelTitle eyebrow="PERFORMANCE PROFILE" title="Resource limits"><select value={config.profile} onChange={(event) => onChange(event.target.value as PerformanceConfig["profile"])}><option value="low">Low — 25 queued / 8 active</option><option value="balanced">Balanced — 100 queued / 24 active</option><option value="high">High — 120 queued / 48 active</option></select></PanelTitle><p className="muted">Limits protect CPU/RAM and never claim an FPS guarantee.</p></article>; }
function ProfileCard({ onOperation }: { onOperation: (operation: "export" | "import" | "backup") => void }) { return <article className="panel profile-card"><PanelTitle eyebrow="PERSISTENCE" title="Profiles and backup" /><p className="muted">Export or import gifts and effect rules, or create a recoverable SQLite backup. The app asks for the destination path before writing.</p><div className="profile-actions"><button onClick={() => onOperation("export")}>Export profile</button><button onClick={() => onOperation("import")}>Import profile</button><button onClick={() => onOperation("backup")}>Backup SQLite</button></div></article>; }
function TikTokControls({ username, setUsername, onStart, onStop }: { username: string; setUsername: (value: string) => void; onStart: () => void; onStop: () => void }) { return <article className="panel tiktok-controls"><PanelTitle eyebrow="TIKTOK LIVE" title="Connector"><span className="counter">username required</span></PanelTitle><div className="connector-form"><input aria-label="TikTok username" placeholder="@username" value={username} onChange={(event) => setUsername(event.target.value)} /><button onClick={onStart}>Connect LIVE</button><button className="secondary" onClick={onStop}>Disconnect</button></div><p className="muted">Uses the local TikTokLive adapter. The connector reconnects automatically when the LIVE is temporarily unavailable.</p></article>; }
function PanelTitle({ eyebrow, title, children }: { eyebrow: string; title: string; children?: ReactNode }) { return <div className="panel-title"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2></div>{children}</div>; }
function ChaosPanel({ chaos }: { chaos: { points: number; level: number } }) { return <article className="panel chaos-panel"><PanelTitle eyebrow="SYSTEM PRESSURE" title="Chaos level"><strong className="level">{String(chaos.level).padStart(2, "0")}</strong></PanelTitle><div className="meter"><span style={{ width: `${chaos.points}%` }}></span></div><div className="scale"><span>NORMAL</span><span>LEVELED</span><span>APOCALYPSE</span></div><p className="muted">{chaos.points ? `${Math.round(chaos.points)} pressure points active.` : "No effects are active."} Emergency Stop clears the queue.</p></article>; }
function GiftManager({ catalog, activeGiftCount }: { catalog: Gift[]; activeGiftCount: number }) { return <article className="panel wide"><PanelTitle eyebrow="CATALOG / LIVE DATA" title="Gift manager"><span className="counter">{activeGiftCount} active</span></PanelTitle><p className="muted">Only gifts configured by the connector or dashboard appear here. Unverified costs remain pending.</p><div className="gift-table"><div className="table-head"><span>GIFT</span><span>COST</span><span>EFFECT</span><span>STATUS</span></div>{catalog.length === 0 ? <div className="empty-row">No gifts configured yet. Connect TikTok or send a test gift.</div> : catalog.map((gift) => <div className="table-row" key={gift.id}><strong>{gift.imageUrl && <img className="gift-thumb" src={gift.imageUrl} alt="" />}{gift.name}</strong><span>{gift.costVerified ? `${gift.coinCost} coins` : "pending"}</span><span>{gift.effectIds.join(", ") || "—"}</span><span className="tag">{gift.active ? "active" : "off"}</span></div>)}</div></article>; }
function GiftEffectReference({ catalog, configs }: { catalog: Gift[]; configs: EffectConfig[] }) { const ids = [...new Set(catalog.flatMap((gift) => gift.effectIds))]; const rows = ids.map((id) => { const definition = effects.find((effect) => effect.id === id); const config = configs.find((item) => item.id === id); return { id, name: config?.name || definition?.name || id, duration: config?.defaultDurationMs ?? 3000, intensity: config?.intensity ?? 1, cooldown: config?.cooldownMs ?? 1000, configured: Boolean(config) }; }); return <article className="panel wide"><PanelTitle eyebrow="ASSIGNED EFFECT DETAILS" title="Gift configuration reference"><span className="counter">{rows.length} assigned</span></PanelTitle><p className="muted">Duration, intensity and cooldown come from the effect configuration and are applied to every gift assigned to that effect. Defaults are shown until saved.</p>{rows.length === 0 ? <p className="muted">Assign an implemented effect to a gift to see its runtime parameters here.</p> : <div className="gift-table"><div className="table-head"><span>EFFECT</span><span>DURATION</span><span>INTENSITY</span><span>COOLDOWN</span></div>{rows.map((row) => <div className="table-row" key={row.id}><strong>{row.name}<small>{row.id} · {row.configured ? "saved" : "default"}</small></strong><span>{row.duration} ms</span><span>{Math.round(row.intensity * 100)}%</span><span>{row.cooldown} ms</span></div>)}</div>}</article>; }
function GiftManagerEditor({ catalog, activeGiftCount, onUpsert, onRemove }: { catalog: Gift[]; activeGiftCount: number; onUpsert: (gift: Gift) => void; onRemove: (id: string) => void }) {
  const [id, setId] = useState(""); const [name, setName] = useState(""); const [imageUrl, setImageUrl] = useState(""); const [imageError, setImageError] = useState(""); const [cost, setCost] = useState(""); const [effectIds, setEffectIds] = useState(["player.ragdoll"]); const [requiredQuantity, setRequiredQuantity] = useState("1"); const [cooldownMs, setCooldownMs] = useState("1000"); const [priority, setPriority] = useState("1");
  const [query, setQuery] = useState(""); const [showInactive, setShowInactive] = useState(false);
  function positiveInt(value: string, fallback: number) { const parsed = Number(value); return Number.isInteger(parsed) && parsed > 0 ? parsed : fallback; }
  function submit(event: FormEvent) { event.preventDefault(); if (!id.trim() || !name.trim() || effectIds.length === 0 || imageError) return; const numericCost = Number(cost); const costVerified = Number.isInteger(numericCost) && numericCost > 0; onUpsert({ id: id.trim(), name: name.trim(), imageUrl: imageUrl.trim() || undefined, coinCost: costVerified ? numericCost : undefined, costVerified, active: true, requiredQuantity: positiveInt(requiredQuantity, 1), effectIds, cooldownMs: Math.max(0, positiveInt(cooldownMs, 1000)), priority: Math.max(0, Number(priority) || 1) }); setId(""); setName(""); setImageUrl(""); setImageError(""); setCost(""); setEffectIds(["player.ragdoll"]); }
  function loadImage(file: File | undefined) { if (!file) return; if (!/^image\/(?:png|jpe?g|gif|webp)$/i.test(file.type)) { setImageError("Use PNG, JPEG, GIF or WebP."); return; } if (file.size > 512 * 1024) { setImageError("The manual icon must be 512 KB or smaller."); return; } const reader = new FileReader(); reader.onload = () => { const result = typeof reader.result === "string" ? reader.result : ""; setImageUrl(result); setImageError(""); }; reader.onerror = () => setImageError("The image could not be read."); reader.readAsDataURL(file); }
  function loadGift(gift: Gift) { setId(gift.id); setName(gift.name); setImageUrl(gift.imageUrl || ""); setImageError(""); setCost(gift.costVerified && gift.coinCost ? String(gift.coinCost) : ""); setEffectIds(gift.effectIds.length ? gift.effectIds : ["player.ragdoll"]); setRequiredQuantity(String(gift.requiredQuantity || 1)); setCooldownMs(String(gift.cooldownMs || 0)); setPriority(String(gift.priority || 0)); }
  function toggleEffect(effectId: string) { setEffectIds((current) => current.includes(effectId) ? current.filter((id) => id !== effectId) : [...current, effectId]); }
  const visibleCatalog = catalog.filter((gift) => (showInactive || gift.active) && `${gift.name} ${gift.id} ${gift.effectIds.join(" ")}`.toLowerCase().includes(query.trim().toLowerCase())).sort((a, b) => { if (a.active !== b.active) return a.active ? -1 : 1; if (a.costVerified !== b.costVerified) return a.costVerified ? -1 : 1; if (a.costVerified && b.costVerified && a.coinCost !== b.coinCost) return (a.coinCost || Number.MAX_SAFE_INTEGER) - (b.coinCost || Number.MAX_SAFE_INTEGER); return a.name.localeCompare(b.name); });
  const targetMessage = activeGiftCount < 20 ? `Only ${activeGiftCount} active gift${activeGiftCount === 1 ? " is" : "s are"} available. The overlay will show only observed gifts; none are invented to reach 20.` : activeGiftCount > 30 ? `${activeGiftCount} active gifts are configured. The overlay defaults to 30 visible cards and can rotate the remainder.` : `${activeGiftCount} active gifts fit the default 20–30 card target.`;
  return <article className="panel wide"><PanelTitle eyebrow="CATALOG / LIVE DATA" title="Gift manager"><span className="counter">{activeGiftCount} active</span></PanelTitle><p className="muted">Only gifts configured by the connector or dashboard appear here. Leave cost empty when it is not verified.</p><p className="catalog-target-warning" role="status">{targetMessage}</p><form className="gift-form" onSubmit={submit}><input aria-label="Gift ID" placeholder="Stable gift ID" value={id} onChange={(event) => setId(event.target.value)} /><input aria-label="Gift name" placeholder="Gift name" value={name} onChange={(event) => setName(event.target.value)} /><input aria-label="Gift image URL" placeholder="Official image URL (optional)" value={imageUrl.startsWith("data:") ? "" : imageUrl} onChange={(event) => { setImageUrl(event.target.value); setImageError(""); }} /><label className="image-upload">Manual icon <input aria-label="Upload manual gift icon" type="file" accept="image/png,image/jpeg,image/gif,image/webp" onChange={(event) => loadImage(event.target.files?.[0])} /></label>{imageError && <span className="image-error" role="alert">{imageError}</span>}<input aria-label="Verified coin cost" placeholder="Verified coins (optional)" inputMode="numeric" value={cost} onChange={(event) => setCost(event.target.value)} /><fieldset className="effect-picker"><legend>Effects</legend>{effects.filter((effect) => effect.state === "implemented").map((effect) => <label key={effect.id}><input type="checkbox" checked={effectIds.includes(effect.id)} onChange={() => toggleEffect(effect.id)} />{effect.id}</label>)}</fieldset><input aria-label="Required quantity" type="number" min="1" step="1" placeholder="Qty" value={requiredQuantity} onChange={(event) => setRequiredQuantity(event.target.value)} /><input aria-label="Cooldown milliseconds" type="number" min="0" step="100" placeholder="Cooldown ms" value={cooldownMs} onChange={(event) => setCooldownMs(event.target.value)} /><input aria-label="Priority" type="number" min="0" step="1" placeholder="Priority" value={priority} onChange={(event) => setPriority(event.target.value)} /><button type="submit">Save gift</button></form><div className="catalog-tools"><input aria-label="Search gifts" placeholder="Search by name, ID or effect" value={query} onChange={(event) => setQuery(event.target.value)} /><label><input type="checkbox" checked={showInactive} onChange={(event) => setShowInactive(event.target.checked)} /> Show inactive</label><span>{visibleCatalog.length} shown</span></div><div className="gift-table"><div className="table-head"><span>GIFT</span><span>COST</span><span>EFFECT</span><span>STATUS</span></div>{catalog.length === 0 ? <div className="empty-row">No gifts configured yet. Connect TikTok or add one above.</div> : visibleCatalog.length === 0 ? <div className="empty-row">No gifts match the current filters.</div> : visibleCatalog.map((gift) => <div className="table-row" key={gift.id}><strong>{gift.imageUrl && <img className="gift-thumb" src={safeImageUrl(gift.imageUrl)} alt="" />}{gift.name}<small>{gift.id} · ×{gift.requiredQuantity} · {gift.cooldownMs}ms · P{gift.priority}</small></strong><span>{gift.costVerified ? `${gift.coinCost} coins` : "pending"}</span><span>{gift.effectIds.join(", ") || "—"}</span><span className="tag">{gift.active ? "active" : "off"}</span><span className="row-actions"><button type="button" className="inline-action" onClick={() => loadGift(gift)}>Edit</button><button type="button" className="inline-action" onClick={() => onUpsert({ ...gift, active: !gift.active })}>{gift.active ? "Disable" : "Enable"}</button><button type="button" className="inline-action danger-action" onClick={() => { if (window.confirm(`Remove ${gift.name} from the catalog?`)) onRemove(gift.id); }}>Remove</button></span></div>)}</div></article>;
}
function MetadataEditor({ label, value, onChange }: { label: string; value?: Record<string, unknown>; onChange: (value: Record<string, unknown>) => void }) {
  const [text, setText] = useState(JSON.stringify(value ?? {}, null, 2));
  useEffect(() => { setText(JSON.stringify(value ?? {}, null, 2)); }, [value]);
  function commit(next: string) {
    setText(next);
    try {
      const parsed: unknown = JSON.parse(next);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) onChange(parsed as Record<string, unknown>);
    } catch { /* Keep the draft visible until it becomes valid JSON. */ }
  }
  return <label>{label}<textarea rows={4} value={text} onChange={(event) => commit(event.target.value)} onBlur={() => { try { const parsed: unknown = JSON.parse(text); if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("metadata must be an object"); onChange(parsed as Record<string, unknown>); } catch { setText(JSON.stringify(value ?? {}, null, 2)); } }} /></label>;
}

function EffectsView({ configs, onSave, onTest }: { configs: EffectConfig[]; onSave: (config: EffectConfig) => void; onTest: (effectId: string, parameters: Record<string, number>) => void }) {
  const [wantedLevel, setWantedLevel] = useState("2");
  const [drafts, setDrafts] = useState<Record<string, EffectConfig>>({});
  const bounded = (value: number, min: number, max: number) => Math.max(min, Math.min(max, Number.isFinite(value) ? value : min));
  function configFor(effect: (typeof effects)[number]): EffectConfig { return drafts[effect.id] || configs.find((config) => config.id === effect.id) || { id: effect.id, name: effect.name, description: `${effect.name} effect`, category: effect.category, defaultDurationMs: 3000, intensity: 1, probability: 1, cooldownMs: 1000, priority: 0, compatibility: "both", updatedAt: new Date().toISOString() }; }
  function update(effectId: string, patch: Partial<EffectConfig>) { const effect = effects.find((item) => item.id === effectId)!; setDrafts((current) => ({ ...current, [effectId]: { ...configFor(effect), ...patch } })); }
  useEffect(() => { const pending = Object.values(drafts); if (!pending.length) return; const timer = window.setTimeout(() => { for (const config of pending) onSave({ ...config, updatedAt: new Date().toISOString() }); }, 600); return () => window.clearTimeout(timer); }, [drafts]);
  function parametersFor(effectId: string): Record<string, number> { const effect = effects.find((item) => item.id === effectId)!; const config = configFor(effect); if (effectId === "player.wanted_level") return { level: bounded(Number(wantedLevel), 0, 5) }; if (effectId === "player.ragdoll" || effectId === "player.invincibility") return { durationMs: bounded(config.defaultDurationMs, 250, 10000) }; if (effectId === "player.super_jump") return { durationMs: bounded(config.defaultDurationMs, 500, 15000) }; if (effectId === "player.speed_boost") return { durationMs: bounded(config.defaultDurationMs, 500, 15000), multiplier: 1.25 }; if (effectId === "vehicle.spin") return { durationMs: bounded(config.defaultDurationMs, 500, 10000), spinRate: 4 }; if (effectId === "world.time") return { durationMs: bounded(config.defaultDurationMs, 1000, 30000), hour: 20, minute: 0 }; if (effectId === "world.weather") return { durationMs: bounded(config.defaultDurationMs, 1000, 30000), weatherIndex: 3 }; return {}; }
  return <article className="panel wide"><PanelTitle eyebrow="EFFECT REGISTRY" title="Effects manager"><span className="counter">{effects.filter((effect) => effect.state === "implemented").length} implemented</span></PanelTitle><p className="muted">Configuration is synchronized with SQLite through the orchestrator. The GTA mod applies its own safety bounds.</p><div className="effect-controls"><label>Wanted level<input type="number" min="0" max="5" step="1" value={wantedLevel} onChange={(event) => setWantedLevel(event.target.value)} /></label></div><div className="effect-grid">{effects.map((effect) => { const config = configFor(effect); return <div className="effect-card" key={effect.id}><small>{effect.category}</small><p>{effect.id}</p><label>Name<input value={config.name} onChange={(event) => update(effect.id, { name: event.target.value })} /></label><label>Description<input value={config.description} onChange={(event) => update(effect.id, { description: event.target.value })} /></label><div className="effect-fields"><label>Duration<input type="number" min="0" max="10000" step="250" value={config.defaultDurationMs} onChange={(event) => update(effect.id, { defaultDurationMs: bounded(Number(event.target.value), 0, 10000) })} /></label><label>Intensity<input type="number" min="0" max="1" step="0.05" value={config.intensity} onChange={(event) => update(effect.id, { intensity: bounded(Number(event.target.value), 0, 1) })} /></label><label>Probability<input type="number" min="0" max="1" step="0.05" value={config.probability} onChange={(event) => update(effect.id, { probability: bounded(Number(event.target.value), 0, 1) })} /></label><label>Cooldown<input type="number" min="0" step="100" value={config.cooldownMs} onChange={(event) => update(effect.id, { cooldownMs: Math.max(0, Math.floor(Number(event.target.value) || 0)) })} /></label><label>Priority<input type="number" min="0" max="100" step="1" value={config.priority ?? 0} onChange={(event) => update(effect.id, { priority: Math.max(0, Math.min(100, Math.floor(Number(event.target.value) || 0))) })} /></label></div><label>Compatibility<select value={config.compatibility} onChange={(event) => update(effect.id, { compatibility: event.target.value as EffectConfig["compatibility"] })}><option value="both">Legacy + Enhanced</option><option value="legacy">Legacy only</option><option value="enhanced">Enhanced only</option></select></label><MetadataEditor label="Parameters (JSON)" value={config.parameters} onChange={(parameters) => update(effect.id, { parameters })} /><MetadataEditor label="Conditions (JSON)" value={config.conditions} onChange={(conditions) => update(effect.id, { conditions })} /><span className={`tag ${effect.state}`}>{effect.state}</span><div className="effect-actions"><button className="effect-test" onClick={() => onSave({ ...config, updatedAt: new Date().toISOString() })}>Save config</button>{effect.state === "implemented" && <button className="effect-test" onClick={() => onTest(effect.id, parametersFor(effect.id))}>Test effect</button>}</div></div>; })}</div></article>;
}
function OverlayViewFunctional({ catalog, chaos, chaosToken, onConfigChange }: { catalog: Gift[]; chaos: { points: number; level: number }; chaosToken: string; onConfigChange: (config: OverlayConfig) => void }) {
  const [copied, setCopied] = useState(false);
  const [sourcePath, setSourcePath] = useState(() => localStorage.getItem("gcl.overlay.sourcePath") || "/overlay/vertical");
  const [gameplayShare, setGameplayShare] = useState(() => Number(localStorage.getItem("gcl.overlay.gameplayShare") || 65));
  const [columns, setColumns] = useState(() => Number(localStorage.getItem("gcl.overlay.columns") || 5));
  const [visibleCount, setVisibleCount] = useState(() => Number(localStorage.getItem("gcl.overlay.visibleCount") || 20));
  const [compact, setCompact] = useState(() => localStorage.getItem("gcl.overlay.compact") === "true");
  const [fontScale, setFontScale] = useState(() => Number(localStorage.getItem("gcl.overlay.fontScale") || 1));
  const [gap, setGap] = useState(() => Number(localStorage.getItem("gcl.overlay.gap") || 10));
  const [backgroundOpacity, setBackgroundOpacity] = useState(() => Number(localStorage.getItem("gcl.overlay.backgroundOpacity") || 0.92));
  const [alertDurationMs, setAlertDurationMs] = useState(() => Number(localStorage.getItem("gcl.overlay.alertDurationMs") || 4000));
  const [soundEnabled, setSoundEnabled] = useState(() => localStorage.getItem("gcl.overlay.soundEnabled") !== "false");
  const [iconScale, setIconScale] = useState(() => Number(localStorage.getItem("gcl.overlay.iconScale") || 1));
  const [cardBackground, setCardBackground] = useState(() => localStorage.getItem("gcl.overlay.cardBackground") || "#272d22");
  const [cardBorder, setCardBorder] = useState(() => localStorage.getItem("gcl.overlay.cardBorder") || "#5c694b");
  const url = `http://127.0.0.1:39178${sourcePath}?token=${encodeURIComponent(chaosToken)}`;
  useEffect(() => { localStorage.setItem("gcl.overlay.sourcePath", sourcePath); localStorage.setItem("gcl.overlay.gameplayShare", String(gameplayShare)); localStorage.setItem("gcl.overlay.columns", String(columns)); localStorage.setItem("gcl.overlay.visibleCount", String(visibleCount)); localStorage.setItem("gcl.overlay.compact", String(compact)); localStorage.setItem("gcl.overlay.fontScale", String(fontScale)); localStorage.setItem("gcl.overlay.gap", String(gap)); localStorage.setItem("gcl.overlay.backgroundOpacity", String(backgroundOpacity)); localStorage.setItem("gcl.overlay.alertDurationMs", String(alertDurationMs)); localStorage.setItem("gcl.overlay.soundEnabled", String(soundEnabled)); localStorage.setItem("gcl.overlay.iconScale", String(iconScale)); localStorage.setItem("gcl.overlay.cardBackground", cardBackground); localStorage.setItem("gcl.overlay.cardBorder", cardBorder); }, [sourcePath, gameplayShare, columns, visibleCount, compact, fontScale, gap, backgroundOpacity, alertDurationMs, soundEnabled, iconScale, cardBackground, cardBorder]);
  useEffect(() => { onConfigChange({ gameplayShare: Math.max(55, Math.min(75, gameplayShare)), columns: (columns === 4 || columns === 5 || columns === 6 ? columns : 5) as OverlayConfig["columns"], visibleCount: Math.max(1, Math.min(30, visibleCount)), compact, fontScale: Math.max(0.75, Math.min(1.25, fontScale)), gap: Math.max(0, Math.min(20, Math.round(gap))), backgroundOpacity: Math.max(0, Math.min(1, backgroundOpacity)), alertDurationMs: Math.max(1000, Math.min(10000, Math.round(alertDurationMs))), soundEnabled, iconScale: Math.max(0.75, Math.min(1.5, iconScale)), cardBackground: /^#[0-9a-fA-F]{6}$/.test(cardBackground) ? cardBackground : "#272d22", cardBorder: /^#[0-9a-fA-F]{6}$/.test(cardBorder) ? cardBorder : "#5c694b" }); }, [gameplayShare, columns, visibleCount, compact, fontScale, gap, backgroundOpacity, alertDurationMs, soundEnabled, iconScale, cardBackground, cardBorder]);
  async function copyUrl() { await navigator.clipboard.writeText(url); setCopied(true); setTimeout(() => setCopied(false), 1600); }
  const visibleCatalog = (catalog.length ? catalog.filter((gift) => gift.active) : [{ id: "empty", name: "Configure gifts", costVerified: false, active: true, requiredQuantity: 1, effectIds: [], cooldownMs: 0, priority: 0 }]).sort((a, b) => { if (a.costVerified !== b.costVerified) return a.costVerified ? -1 : 1; if (a.costVerified && b.costVerified && a.coinCost !== b.coinCost) return (a.coinCost || Number.MAX_SAFE_INTEGER) - (b.coinCost || Number.MAX_SAFE_INTEGER); return a.name.localeCompare(b.name); }).slice(0, visibleCount);
  const tooSmall = visibleCount > 20 || visibleCatalog.length > 20;
  return <div className="studio-grid"><article className="panel preview"><PanelTitle eyebrow="OBS BROWSER SOURCE" title="TikTok Vertical Chaos" /><div className="phone"><div className="phone-game" style={{ height: `${gameplayShare}%` }}>GAMEPLAY SPACE<div className="mini-chaos">CHAOS {chaos.level}</div></div><div className={`phone-catalog ${compact ? "compact" : ""}`} style={{ height: `${100 - gameplayShare}%`, gridTemplateColumns: `repeat(${columns}, 1fr)`, gap: `${gap}px`, opacity: backgroundOpacity, ["--card-background" as string]: cardBackground, ["--card-border" as string]: cardBorder, ["--icon-scale" as string]: iconScale }}>{visibleCatalog.map((gift) => <div className="preview-gift" key={gift.id}>{safeImageUrl(gift.imageUrl) ? <img className="gift-thumb" src={safeImageUrl(gift.imageUrl)} alt="" /> : <span className="preview-icon-fallback" aria-label="Gift icon unavailable">NO ICON</span>}<strong>{gift.name}</strong><small>{gift.costVerified ? `${gift.coinCost} coins` : "cost pending"}{gift.requiredQuantity > 1 ? ` · ×${gift.requiredQuantity}` : ""}</small><small>{gift.effectIds.length ? gift.effectIds.map(effectLabel).join(" · ") : "no effect assigned"}</small></div>)}</div></div>{tooSmall && <p className="studio-warning">Warning: this configuration may reduce gift-card legibility. Use pagination or fewer visible gifts.</p>}</article><article className="panel settings"><PanelTitle eyebrow="OBS SETUP" title="Layout & style" /><label>Canvas <input value="1080 × 1920" readOnly /></label><label>OBS source <select value={sourcePath} onChange={(event) => setSourcePath(event.target.value)}><option value="/overlay/vertical">Vertical — complete preset</option><option value="/overlay/gifts">Gifts — catalog source</option><option value="/overlay/alerts">Alerts — alert source</option><option value="/overlay/chaos">Chaos — chaos indicator</option></select></label><label>Gameplay share <input type="range" min="55" max="75" value={gameplayShare} onChange={(event) => setGameplayShare(Number(event.target.value))} /><span>{gameplayShare}% gameplay / {100 - gameplayShare}% catalog</span></label><label>Catalog columns <select value={columns} onChange={(event) => setColumns(Number(event.target.value))}><option value={4}>4 columns</option><option value={5}>5 columns</option><option value={6}>6 columns</option></select></label><label>Visible gifts <input type="range" min="10" max="30" value={visibleCount} onChange={(event) => setVisibleCount(Number(event.target.value))} /><span>{visibleCount} cards maximum</span></label><label className="settings-check">Compact cards <input type="checkbox" checked={compact} onChange={(event) => setCompact(event.target.checked)} /></label><label>Font scale <input type="range" min="0.75" max="1.25" step="0.05" value={fontScale} onChange={(event) => setFontScale(Number(event.target.value))} /><span>{fontScale.toFixed(2)}×</span></label><label>Icon scale <input type="range" min="0.75" max="1.5" step="0.05" value={iconScale} onChange={(event) => setIconScale(Number(event.target.value))} /><span>{iconScale.toFixed(2)}×</span></label><label>Card spacing <input type="range" min="0" max="20" step="1" value={gap} onChange={(event) => setGap(Number(event.target.value))} /><span>{gap}px</span></label><label>Catalog opacity <input type="range" min="0" max="1" step="0.05" value={backgroundOpacity} onChange={(event) => setBackgroundOpacity(Number(event.target.value))} /><span>{Math.round(backgroundOpacity * 100)}%</span></label><label>Card background <input type="color" value={cardBackground} onChange={(event) => setCardBackground(event.target.value)} /></label><label>Card border <input type="color" value={cardBorder} onChange={(event) => setCardBorder(event.target.value)} /></label><label>Alert duration <input type="range" min="1000" max="10000" step="500" value={alertDurationMs} onChange={(event) => setAlertDurationMs(Number(event.target.value))} /><span>{(alertDurationMs / 1000).toFixed(1)}s</span></label><label className="settings-check">Alert sound <input type="checkbox" checked={soundEnabled} onChange={(event) => setSoundEnabled(event.target.checked)} /></label><div className="url-box"><code>{url}</code><button onClick={copyUrl}>{copied ? "Copied" : "Copy URL"}</button></div><ol className="setup-steps"><li>Add a Browser Source in OBS.</li><li>Paste the selected URL above.</li><li>Set width 1080 and height 1920.</li><li>Keep the background transparent.</li></ol></article></div>;
}
function OverlayView({ catalog, chaos }: { catalog: Gift[]; chaos: { points: number; level: number } }) { return <div className="studio-grid"><article className="panel preview"><PanelTitle eyebrow="OBS BROWSER SOURCE" title="TikTok Vertical Chaos" /><div className="phone"><div className="phone-game">GAMEPLAY SPACE<div className="mini-chaos">CHAOS {chaos.level}</div></div><div className="phone-catalog">{(catalog.length ? catalog : [{ id: "empty", name: "Configure gifts", costVerified: false, active: true, requiredQuantity: 1, effectIds: [], cooldownMs: 0, priority: 0 }]).slice(0, 10).map((gift) => <div key={gift.id}>{gift.name}<small>{gift.costVerified ? gift.coinCost : "pending"}</small></div>)}</div></div></article><article className="panel settings"><PanelTitle eyebrow="STUDIO SETTINGS" title="Layout" /><label>Canvas <input value="1080 × 1920" readOnly /></label><label>Gameplay share <input value="65%" readOnly /></label><label>Catalog columns <input value="5" readOnly /></label><p className="muted">The live OBS URL is stable at <code>http://127.0.0.1:39178/</code>.</p></article></div>; }
function AnalyticsView({ events, catalog, stats, breakdown }: { events: EventLine[]; catalog: Gift[]; stats: Stats; breakdown: AnalyticsBreakdown }) { return <div className="analytics-grid"><article className="metric"><small>GIFTS RECEIVED</small><strong>{stats.giftsReceived}</strong></article><article className="metric"><small>EFFECTS SUCCEEDED</small><strong>{stats.effectsSucceeded}</strong></article><article className="metric"><small>ACTIVE GIFTS</small><strong>{catalog.filter((gift) => gift.active).length}</strong></article><article className="metric"><small>FAILURES</small><strong>{stats.effectsFailed}</strong></article><article className="metric"><small>QUEUE DEPTH</small><strong>{stats.queueDepth ?? 0}</strong></article><article className="metric"><small>ACTIVE EFFECTS</small><strong>{stats.activeEffects ?? 0}</strong></article><article className="metric"><small>AVG LATENCY</small><strong>{stats.averageLatencyMs ?? 0}<small> ms</small></strong></article><article className="panel wide"><div className="analytics-breakdown"><BreakdownList title="GIFTS BY TYPE" values={breakdown.gifts} /><BreakdownList title="TOP EFFECTS" values={breakdown.effects} /><BreakdownList title="TOP USERS" values={breakdown.users} /></div></article><article className="panel wide"><PanelTitle eyebrow="SESSION LOG" title="Recent activity" /><div className="events">{events.length ? events.map((event) => <EventRow event={event} key={event.id} />) : <p className="muted">No events recorded in this dashboard session.</p>}</div></article></div>; }
function BreakdownList({ title, values }: { title: string; values: Record<string, number> }) { const rows = Object.entries(values).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 5); return <section><small>{title}</small>{rows.length ? rows.map(([name, count]) => <p key={name}><span>{name}</span><strong>{count}</strong></p>) : <p className="muted">No session data yet.</p>}</section>; }
function LiveMonitorView({ events, stats, streamState }: { events: EventLine[]; stats: Stats; streamState: string }) { return <div className="analytics-grid"><article className="metric"><small>STREAM</small><strong>{streamState}</strong></article><article className="metric"><small>GIFTS RECEIVED</small><strong>{stats.giftsReceived}</strong></article><article className="metric"><small>QUEUE / ACTIVE</small><strong>{stats.queueDepth ?? 0} / {stats.activeEffects ?? 0}</strong></article><article className="panel wide"><PanelTitle eyebrow="REAL-TIME EVENT STREAM" title="Live Monitor"><span className="counter">{events.length} recent</span></PanelTitle><p className="muted">Received, queued, succeeded, rejected and failed events appear here with their backend status and latency.</p><div className="events"><div className="event-row event-head"><span>TIME</span><span>USER</span><span>GIFT / QTY</span><span>EFFECT</span><span>STATUS</span><span>LATENCY</span><span>ERROR</span></div>{events.length ? events.map((event) => <EventRow event={event} key={event.id} />) : <p className="muted">No events recorded yet. Start the simulator or connect TikTok LIVE.</p>}</div></article></div>; }
function SessionHistory({ sessions }: { sessions: SessionSummary[] }) { return <article className="panel wide session-history"><PanelTitle eyebrow="SESSION HISTORY" title="Statistics by transmission" /><div className="session-table"><div className="table-head"><span>STARTED</span><span>GIFTS</span><span>QUEUED</span><span>SUCCEEDED</span><span>FAILED</span></div>{sessions.length ? sessions.map((session) => <div className="table-row" key={session.id}><span>{new Date(session.startedAt).toLocaleString()}</span><span>{session.giftsReceived}</span><span>{session.effectsQueued}</span><span>{session.effectsSucceeded}</span><span>{session.effectsFailed}</span></div>) : <p className="muted">No persisted sessions yet.</p>}</div></article>; }

createRoot(document.getElementById("root")!).render(<App />);
